#[derive(Default)]
struct SharedDecodedTextureCacheInner {
    srgb: std::collections::HashMap<(usize, usize), CachedDecodedTexture>,
    linear: std::collections::HashMap<(usize, usize), CachedDecodedTexture>,
}

/// Device-scoped GPU texture residency shared by independent preview renderers.
#[derive(Clone, Default)]
pub(crate) struct SharedDecodedTextureCache {
    inner: Arc<Mutex<SharedDecodedTextureCacheInner>>,
}

enum DecodedTextureResolve {
    Hit(Arc<Texture>),
    Uploaded(Arc<Texture>),
    Deferred,
    Failed,
}

impl SharedDecodedTextureCache {
    fn device_key(device: &wgpu::Device) -> usize {
        std::ptr::from_ref(device).addr()
    }

    fn retain_live(&self) {
        let mut inner = self.inner.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        inner.srgb.retain(|_, cached| cached.source.strong_count() > 0);
        inner.linear.retain(|_, cached| cached.source.strong_count() > 0);
    }

    fn resolve(
        &self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        pending: &Arc<DecodedTexture>,
        encoding: TextureSampleEncoding,
        allow_upload: bool,
    ) -> DecodedTextureResolve {
        let key = (Self::device_key(device), Arc::as_ptr(pending) as usize);
        let mut inner = self.inner.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        let cache = match encoding {
            TextureSampleEncoding::SrgbColor => &mut inner.srgb,
            TextureSampleEncoding::LinearData => &mut inner.linear,
        };
        if let Some(cached) = cache.get(&key) {
            return DecodedTextureResolve::Hit(Arc::clone(&cached.texture));
        }
        if !allow_upload {
            return DecodedTextureResolve::Deferred;
        }
        let uploaded = match encoding {
            TextureSampleEncoding::SrgbColor => Texture::from_decoded(device, queue, pending),
            TextureSampleEncoding::LinearData => Texture::from_decoded_linear(device, queue, pending),
        };
        let Ok(texture) = uploaded else {
            return DecodedTextureResolve::Failed;
        };
        let texture = Arc::new(texture);
        cache.insert(
            key,
            CachedDecodedTexture {
                source: Arc::downgrade(pending),
                texture: Arc::clone(&texture),
            },
        );
        DecodedTextureResolve::Uploaded(texture)
    }

    pub(crate) fn clear(&self) {
        let mut inner = self.inner.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        inner.srgb.clear();
        inner.linear.clear();
    }

    #[cfg(test)]
    fn live_counts(&self) -> (usize, usize) {
        let inner = self.inner.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        (inner.srgb.len(), inner.linear.len())
    }
}

